{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early signs of bearishness.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor.",
    "Apply mean reversion bias: if forecast is significantly above recent 7-day average, reduce by 5-10%.",
    "Increase forecast sensitivity to sentiment shifts: if sentiment turns positive after a downtrend, raise forecast by 3-5%.",
    "Avoid over-optimism in early forecast windows (1-3 days ahead) — use lagged 7-day average as baseline for short-term correction."
  ]
}

{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early negative momentum.",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor.",
    "Apply mean reversion bias: if forecast deviates >5% from recent 7-day average, adjust toward it.",
    "Increase forecast sensitivity to recent sentiment shifts — especially when sentiment turns positive after a dip.",
    "For long-term (30-day) forecasts, reduce overconfidence in upward trends when sentiment is neutral or mildly negative.",
    "When sentiment shows early positive momentum, slightly increase forecast lag to avoid premature peaks."
  ]
}

{
  "correction_rules": [
    "Reduce forecast overshoots after sharp price spikes (especially when sentiment is neutral or negative).",
    "Adjust forecasts downward if recent history shows strong mean reversion toward lower prices.",
    "Apply a mild downward bias when sentiment history is consistently neutral or negative (no strong bullish signal).",
    "Avoid overreacting to short-term volatility; smooth out forecast curves for 30-day horizons.",
    "If true outcome consistently underperforms model forecast, reduce forecast amplitude by 5-10% for next period.",
    "When sentiment history includes a single positive value, treat it as a signal to slightly increase forecast, but not exceed prior 3-day average."
  ]
}

{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes (especially after sentiment > 0.0).",
    "Apply downward bias correction when sentiment is negative or near-zero, particularly in early forecast windows.",
    "Adjust for mean reversion: if forecast is significantly above recent 7-day average, reduce by 5-10% in next 3-5 days.",
    "Increase downward adjustment if true outcome consistently underperforms forecast by >3% over 3-5 days (especially with negative sentiment).",
    "Avoid overconfidence in short-term forecasts when sentiment is volatile or near-zero — use 30-day moving average as baseline anchor."
  ]
